{"filename": "test_letter_grade.py", "content": "import os
import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
letter_grade = target.letter_grade


def test_cutoff_90_is_A():
    """Spec: Scores exactly equal to a cutoff receive the higher grade. 90 is A."""
    assert letter_grade(90) == "A"


def test_cutoff_80_is_B():
    """Spec: 80 is B."""
    assert letter_grade(80) == "B"


def test_cutoff_70_is_C():
    """Spec: 70 is C."""
    assert letter_grade(70) == "C"


def test_cutoff_60_is_D():
    """Spec: 60 is D."""
    assert letter_grade(60) == "D"


def test_above_90_is_A():
    """Spec: scores above 90 get A."""
    assert letter_grade(91) == "A"
    assert letter_grade(100) == "A"


def test_between_80_and_90_is_B():
    """Spec: scores above 80 but below 90 get B."""
    assert letter_grade(85) == "B"
    assert letter_grade(89) == "B"


def test_between_70_and_80_is_C():
    """Spec: scores above 70 but below 80 get C."""
    assert letter_grade(75) == "C"
    assert letter_grade(79) == "C"


def test_between_60_and_70_is_D():
    """Spec: scores above 60 but below 70 get D."""
    assert letter_grade(65) == "D"
    assert letter_grade(69) == "D"


def test_below_60_is_F():
    """Spec: scores below 60 get F."""
    assert letter_grade(59) == "F"
    assert letter_grade(0) == "F"


def test_boundary_values():
    """Spec: 0 is F, 100 is A."""
    assert letter_grade(0) == "F"
    assert letter_grade(100) == "A"


def test_invalid_score_too_low():
    """Score below 0 should raise ValueError."""
    try:
        letter_grade(-1)
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_invalid_score_too_high():
    """Score above 100 should raise ValueError."""
    try:
        letter_grade(101)
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_invalid_score_non_numeric():
    """Non-numeric score should raise TypeError."""
    try:
        letter_grade("A")
        assert False, "Should have raised TypeError"
    except TypeError:
        pass
"}

