def test_basic():
    result = sorted_intersection([1, 2, 3], [2, 3, 4])
    assert result == [2, 3]


def test_no_common():
    result = sorted_intersection([1, 2], [3, 4])
    assert result == []


def test_empty_left():
    result = sorted_intersection([], [1, 2, 3])
    assert result == []


def test_empty_right():
    result = sorted_intersection([1, 2, 3], [])
    assert result == []


def test_both_empty():
    result = sorted_intersection([], [])
    assert result == []


def test_duplicates_left():
    result = sorted_intersection([1, 1, 2, 2, 3], [1, 2, 3])
